const all = $input.all();

function repair(value) {
  let s = String(value ?? '');
  for (let i = 0; i < 2; i++) {
    if (!/[ÃÂâ€šœž™�]/.test(s)) break;
    try {
      const fixed = Buffer.from(s, 'latin1').toString('utf8');
      if (fixed === s || fixed.includes('�')) break;
      s = fixed;
    } catch (e) { break; }
  }
  return s.replace(/\uFFFD/g, '').replace(/\s+/g, ' ').trim();
}
function strip(value) { return repair(String(value ?? '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]*>/g, ' ')); }
function first(obj, keys) { for (const k of keys) { const v = k.split('.').reduce((a,p)=>a?.[p], obj); if (v !== undefined && v !== null && String(v).trim()) return v; } return ''; }
