const out=[]; const seen=new Set();
const now = Date.now();
const maxAgeMs = 24 * 60 * 60 * 1000;
function publishedAt(obj) { return first(obj, ['isoDate','pubDate','published','date','date_published','published_at']); }
function isFresh(value) {
  const t = Date.parse(String(value || ''));
  return Number.isFinite(t) && t <= now + 15 * 60 * 1000 && now - t <= maxAgeMs;
}
for (const item of all) {
  const n=item.json || {};
  const link=String(first(n,['link','url','guid','id']));
