const STOP = new Set(['a','o','e','de','da','do','das','dos','em','no','na','nos','nas','por','para','com','um','uma','que','se','ao','à','as','os','mais','sobre','após','entre','como','não','já','vai','foi','ser','são','é','the','and','for','with']);
const clean = (v) => String(v ?? '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g,' ').replace(/ +/g,' ').trim();
const tokens = (v) => new Set(clean(v).split(' ').filter(w => w.length > 2 && !STOP.has(w)));
const similarity = (a,b) => { if(!a.size || !b.size) return 0; let n=0; for(const w of a) if(b.has(w)) n++; return n/Math.min(a.size,b.size); };
const titleOf = (n) => String(n.titulo || n.title || n.titulo_original || n.name || '').trim();
const linkOf = (n) => String(n.link_original || n.link || n.url || n.guid || '').trim();
const seen = new Set(), stories = [], out = [];
for (const item of $input.all()) {
  const n = item.json || {}, title = titleOf(n), link = linkOf(n);
  const canonical = (link.match(/\*https?:\/\/.+$/)?.[0]?.slice(1) || link).toLowerCase().replace(/[?#].*$/,'').replace(/\/$/,'') || clean(title);
  if (!canonical || seen.has(canonical)) continue;
  const t = tokens(title), duplicate = stories.some(s => similarity(t, s.tokens) >= 0.92);
  if (duplicate) continue;
  seen.add(canonical); stories.push({tokens:t});
  out.push({json:{...n,titulo:title,title,link_original:link,link,story_key:canonical.slice(0,240)}});
}
return out;

const csvResp = await this.helpers.httpRequest({ method: 'GET', url: 'https://docs.google.com/spreadsheets/d/1_tL_kPprM4Q1p7DKunBlFhsTBgfjFU6iHFb_8SCRekc/gviz/tq?tqx=out:csv&sheet=Fontes', timeout: 10000, returnFullResponse: true, ignoreResponseCode: true });
