const seenBase=new Set(); const sources=csvRows(csv).filter(s=>{const st=(s.status||'').toLowerCase(),u=(s.url||'').trim(),base=u.replace(/\/$/,'').toLowerCase(); if(!/^https?:\/\//i.test(u)||(s.rss_url||'').trim()||st.includes('descart')||st.includes('não valid')||st.includes('inval')||st.includes('bloque')||seenBase.has(base)) return false; seenBase.add(base); return true;}).slice(0,20);
const clean=v=>String(v||'').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/\s+/g,' ').trim();
const abs=(h,b)=>{try{return new URL(h,b).href}catch(e){return ''}};
const publishedMeta=(h)=>{const patterns=[/<meta[^>]+(?:property|name)\s*=\s*["']article:published_time["'][^>]+content\s*=\s*["']([^"']+)["']/i,/<meta[^>]+content\s*=\s*["']([^"']+)["'][^>]+(?:property|name)\s*=\s*["']article:published_time["']/i,/<time[^>]+datetime\s*=\s*["']([^"']+)["']/i,/<time[^>]*>([^<]+)<\/time>/i]; for(const p of patterns){const m=String(h).match(p); if(m&&Number.isFinite(Date.parse(m[1]))) return new Date(m[1]).toISOString();} return '';};
const meta=(h)=>{const a=String(h).match(/<meta[^>]+(?:property|name)\s*=\s*["'](?:og:image|twitter:image)["'][^>]+content\s*=\s*["']([^"']+)["']/i); if(a) return a[1].replace(/&amp;/g,'&').trim(); const b=String(h).match(/<meta[^>]+content\s*=\s*["']([^"']+)["'][^>]+(?:property|name)\s*=\s*["'](?:og:image|twitter:image)["']/i); return b?b[1].replace(/&amp;/g,'&').trim():''};
const out=[];
for(const s of sources){let html='';try{const resp=await this.helpers.httpRequest({method:'GET',url:s.url,timeout:7000,headers:{'User-Agent':'Mozilla/5.0 (compatible; DFJA-NewsBot/1.0)'},returnFullResponse:true,ignoreResponseCode:true}); html=typeof resp==='string'?resp:String(resp?.body??resp?.data??'')}catch(e){continue} const img=meta(html); const published=publishedMeta(html); const re=/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi; const seen=new Set(); let m;
  while((m=re.exec(html))&&seen.size<8){const href=abs(m[1],s.url),title=clean(m[2]); if(!href||title.length<25||title.length>220)continue; const u=new URL(href),b=new URL(s.url); if(u.hostname.replace(/^www\./,'')!==b.hostname.replace(/^www\./,'')||/login|entrar|busca|search|tag|autor|facebook|instagram|twitter|youtube|privacidade|termos/i.test(href))continue; if(u.pathname.split('/').filter(Boolean).length<2)continue; const key=href.toLowerCase().replace(/[?#].*$/,'').replace(/\/$/,''); if(seen.has(key))continue; seen.add(key); out.push({json:{titulo:title,title,link:href,url:href,link_original:href,fonte:s.nome||s.url,source:s.nome||s.url,source_kind:'html',coleta_tipo:'html',content:'',description:'',summary:'',imagem_url:img,image_url:img,data_publicacao:published || '',fonte_catalogo_url:s.url}});}}
